cedar_policies:
@id("read_after_login")
permit (
  principal,
  action == Drupe::Action::"Read",
  resource
)
when { context.policy_0__temporal_0 };

cedar_schema:
namespace Drupe {
  type LoginInput = { user: String };
  type ReadInput = { user: String };
  entity Gateway;
  entity OAuthUser = { id: String } tags String;
  action "Login" appliesTo {
    principal: [OAuthUser],
    resource: [Gateway],
    context: { input: LoginInput }
  };
  action "Read" appliesTo {
    principal: [OAuthUser],
    resource: [Gateway],
    context: { input: ReadInput, policy_0__temporal_0: __cedar::Bool }
  };
}
